SELECT *
FROM iam_user
WHERE tenant_id = #{tenantId}
  AND public_id = #{publicId}
  AND deleted = 0
LIMIT 1

SELECT u.id, u.public_id AS publicId, u.tenant_id AS tenantId, u.user_code AS userCode, u.username, u.nickname, u.employee_id AS employeeId, u.user_type AS userType, u.status, u.mobile, u.email, u.remark FROM iam_user u LEFT JOIN iam_employee e ON e.id = u.employee_id AND e.deleted = 0 WHERE u.deleted = 0 AND u.tenant_id = #{spec.tenantId}
AND 1 = 0
OR u.id IN
#{userId}
OR e.dept_id IN
#{departmentId}
OR e.position_id IN
#{positionId}
OR EXISTS ( SELECT 1 FROM iam_user_role ur WHERE ur.tenant_id = u.tenant_id AND ur.user_id = u.id AND ur.deleted = 0 AND ur.role_id IN
#{roleId}
)
ORDER BY u.id DESC

SELECT *
FROM iam_user
WHERE tenant_id = #{tenantId}
  AND username = #{username}
  AND deleted = 0
LIMIT 1
